    public void ClearCard()
    {
        for (int i = 0; i < cardsInArea.Count; i++)
        {
            var c = cardsInArea[i];
            if (c != null && c.gameObject != null)
            {
                Destroy(c.gameObject);
            }
        }
        cardsInArea.Clear();
    }

