    public List<Card> GetSelectedCardData()
    {
        List<Card> selectedCards = new List<Card>();
        foreach (var card in cardsInArea)
        {
            if (card == null) continue;
            if (card.IsSelected)
            {
                selectedCards.Add(card);
            }
        }
        return selectedCards;
    }
}
